import type { TrialInput } from "@/lib/schema";

/**
 * COLORECTAL CANCER: registry-only trial records. Every interventional phase 2, 1/2, 2/3 or 3 trial on
 * ClinicalTrials.gov that on 2026-09-24 was recruiting, not yet recruiting or enrolling by invitation (plus the phase 3
 * and 2/3 trials that are active but closed to recruitment), names colorectal, colon or rectal cancer in its title or
 * conditions, and was not already in the corpus. Generated from the v2 API snapshot cached under /tmp/crc by the
 * colorectal deep dive (the generator is /tmp/crc/gen-registry.py, adapted from the pancreatic one); registry facts
 * only, no outcomes. Trials with results, and the trials that set the standard of care, are hand-written in
 * ./colorectal-treatment-trials.ts and ./colorectal-treatment-trials-advanced.ts. UK sites are quoted in `notes`.
 * Linked from the glossary term `colorectal-trials-open-today` so none is an orphan. Records link to the subtype page
 * the registry text names (colon, rectum, MSI-high, BRAF V600E, HER2-amplified, KRAS G12C, early onset) and to
 * `colorectal` itself only when it names none, so the cancer page stays under its markup ceiling
 * (src/app/record-fold.test.ts). Anal, appendiceal, small-bowel and neuroendocrine-only trials are left out.
 */
const asOf = "2026-09-24";
const tags = ["ctgov-ingest", "colorectal-deep-dive"];
const ct = (nct: string) => ({ label: `ClinicalTrials.gov ${nct}`, url: `https://clinicaltrials.gov/study/${nct}` });

